// ESP32-C3-MINI-1 module outline (metal-shielded, sits on upper half)
const mod = el("g", {}, g);
el("rect", { x: DEV.x - 20, y: topY - 24, width: 140, height: 96, rx: 5,
             fill: "#c8ccd2", stroke: "#8d939c", "stroke-width": 1.5 }, mod);
