edits.newText:
function button(cx, label, tipHtml) {
    const b = el("g", {}, g);
    el("rect", { x: cx - 13, y: usbY - 11, width: 26, height: 22, rx: 4, fill: "#dfe3e8", stroke: "#9aa2ac" }, b);
    el("circle", { cx, cy: usbY, r: 7.5, fill: "#f0f3f6", stroke: "#9aa2ac" }, b);
    txt(cx, usbY - 15, label, { "font-size": 8, fill: "#dfe7f3", "text-anchor": "middle", "font-weight": 600 }, g);
    tipify(b, tipHtml);
  }
  button(DEV.x + 74, "BOOT", "<b>BOOT button</b><br>Holds GPIO0 low. Hold BOOT while pressing RESET to enter download mode.");
  button(DEV.x + 106, "RESET", "<b>RESET button</b><br>Pulls RST (CHIP_PU) low to restart the chip.");

