edits.newText:
function drawBreadboard() {
  const g = el("g", { id: "breadboard" }, svg);
  // body
  const body = el("rect", { x: BB.x - 45, y: BB.y - 42, width: bbW + 90, height: bbH + 84, rx: 10,
               fill: "#f2f3f5", stroke: "#c3c9d1", "stroke-width": 2 }, g);
  tipify(body, "<b>Breadboard (830 tie-points)</b><br>Columns 1–30 × rows a–e / f–j. Each column of 5 holes is ONE electrical node — the center gap separates the two halves.");

edits.oldText:
function rail(yRow, color, sign, name) {
  el("rect", { x: BB.x - 30, y: yRow - 6.5, width: bbW + 60, height: 13, rx: 4, fill: color, opacity: .28 }, g);
  for (let i = 0; i <= 30; i++) {
    const [x, y] = [BB.x + i * BB.pitch, yRow];
    el("circle", { cx: x, cy: y, r: 3.1, fill: "#2b3038" }, g);
  }
  txt(BB.x - 36, yRow + 4, sign, { "font-size": 13, "font-weight": 700, fill: color, "text-anchor": "end" }, g);
}

edits.newText:
function rail(yRow, color, sign, name) {
  const rg = el("g", {}, g);
  el("rect", { x: BB.x - 30, y: yRow - 6.5, width: bbW + 60, height: 13, rx: 4, fill: color, opacity: .28 }, rg);
  for (let i = 0; i <= 30; i++) {
    const [x, y] = [BB.x + i * BB.pitch, yRow];
    el("circle", { cx: x, cy: y, r: 3.1, fill: "#2b3038" }, rg);
  }
  txt(BB.x - 36, yRow + 4, sign, { "font-size": 13, "font-weight": 700, fill: color, "text-anchor": "end" }, g);
  return rg;
}

