cd /home/jlb/dev/tmp/andrisgauracs && chromium --headless --no-sandbox --disable-gpu --window-size=1400,980 --screenshot=shot-default.png "file://$PWD/index.html" 2>&1 | tail -1 && node -e "
const fs=require('fs'); const h=fs.readFileSync('index.html','utf8');
// self-check: pin counts and labels
const j1=[...h.matchAll(/J1 = \[([^\]]*)\]/)][0][1].match(/\"[^\"]+\"/g).length;
const j3=[...h.matchAll(/J3 = \[([^\]]*)\]/)][0][1].match(/\"[^\"]+\"/g).length;
console.log('J1 pins:',j1,' J3 pins:',j3);
// breadboard: cols 1..30, rows a-j
console.log('cols loop ok:', /for \(let c = 1; c <= 30; c\+\+\)/.test(h));
console.log('letters a-j:', h.includes('[\"a\",\"b\",\"c\",\"d\",\"e\"]') && h.includes('concat([\"f\",\"g\",\"h\",\"i\",\"j\"])'));
// flow path endpoints
console.log('flow starts GPIO4:', /P\.gpio4, \[vBus/.test(h), ' ends GND pin:', /\[vBus - 28, P\.gndPin\[1\]\], P\.gndPin/.test(h));
"

